// The English words of every translated screen: the source catalogue (gap list G39).
//
// Each entry is both the key and the English words (src/lib/i18n/t.ts). A screen writes
// t("Sign in"); the other languages translate the same entries in ./hi.ts, ./te.ts and the rest.
// Adding words to a screen: add them here first (the type check refuses t() with words that are
// not here), then to each language; a missing translation shows the English words.
// Words after "@@" only tell two meanings apart and are never shown.
// Keep the screen words of 00-global.md §9 in English here (Fees due, Receipt, Archive, ...).

