  "Ask and Do",
  "Questions in your own words. Ready-made questions per role and typed words such as \"absent today\" or \"fees due class 5\" work without AI. With this on, when the words match no ready-made question, the AI service picks the closest one from the words only; the answer always comes from the school's own lists. Preparing actions as a filled form (Do) is not built yet.",
  "Smart Import",
  "When importing a spreadsheet, suggests which column is which and likely fixes (dates, phone numbers, class names). With the AI service connected, it also suggests columns the rules could not match, from the headings only. You tick each suggestion before it is used.",
  "AI auto-reply to enquiries",
  "Suggests replies to admission enquiries; a person sends them.",
  "Student insights and early warnings",
  "Flags students whose attendance, marks or fees need attention.",
  "Forecasts",
  "Looking ahead from the school's own records: attendance and marks heading below the line, fees likely to come late, seats likely to stay empty, staff and cash.",
  "Principal summary",
  "Today's brief for the Principal and School Admin each school morning, and the weekly brief on Monday: what happened, what may need them next and what waits for their decision. Every number is the school's own record, with a link to the list behind it.",
  "Teacher assistant",
  "Drafts homework, feedback on submissions and report card remarks for the teacher to edit.",
  "AI question papers",
  "Not built: free tools already do this.",
  "Translation of typed messages",
  "Translates a typed message into each parent's language. The sender sees and can edit each translation; the parent's copy says \"Translated from English\".",
  "A CBSE school where children go home each day, with a library and school buses.",
